            document.getElementById('playbackMain').classList.toggle('hidden', !hasShots);
            if (!hasShots) { summary.textContent = 'No shots in this project yet.'; return; }

            renderPlaybackSummary();
            document.getElementById('pbTotalTimecode').textContent = timeline.total_timecode;
